<template><section class="community-panel"><h2>Hoạt động của bạn</h2><p class="community-hint">Cập nhật được lưu trong hệ thống. Trạng thái chờ gửi email không xác nhận đã nhận email.</p><p v-if="loading" role="status">Đang tải hoạt động…</p><p v-else-if="error" role="alert">{{ error }} <button type="button" class="button button-outline" @click="load">Thử lại</button></p><template v-else><p v-if="!data.content.length" class="community-hint">Chưa có hoạt động liên quan.</p><ul class="community-notifications"><li v-for="item in data.content" :key="item.id"><p>{{ item.body.split('\n')[0] }}</p><time :datetime="item.createdAt">{{ date(item.createdAt) }}</time><RouterLink v-if="postPath(item.body)" :to="postPath(item.body)">Mở bài viết</RouterLink></li></ul><nav v-if="data.totalPages>1" class="community-actions" aria-label="Phân trang hoạt động"><button type="button" class="button button-outline" :disabled="!page" @click="page--;load()">Trước</button><button type="button" class="button button-outline" :disabled="page+1>=data.totalPages" @click="page++;load()">Sau</button></nav></template></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {useAuth} from '../../composables/useAuth.js';import {marketplaceRequest as request} from '../../services/marketplace.js';import {date} from '../../services/discussions.js';const {user}=useAuth(),loading=ref(false),error=ref(''),page=ref(0),data=ref({content:[],totalPages:0});let generation=0;const postPath=body=>String(body).match(/\/community\/posts\/\d+/)?.[0];async function load(){const ticket=++generation;loading.value=true;error.value='';data.value={content:[],totalPages:0};if(!user.value){loading.value=false;return;}try{const result=await request('/account/community/notifications?page='+page.value);if(ticket===generation)data.value=result;}catch(e){if(ticket===generation)error.value=e.message;}finally{if(ticket===generation)loading.value=false;}}watch(()=>user.value?.id,()=>{page.value=0;load();},{immediate:true});onBeforeUnmount(()=>generation++);
</script>
